输出：当前CPU的个数是: 14
设置程序使用的CPU个数
package main
import (
	"fmt"
	"runtime"
)
func main() {
	// 获取当前CPU的个数
	cpuNum := runtime.NumCPU()
	fmt.Println("当前CPU的个数是:", cpuNum)
	// 设置程序使用的CPU个数
	runtime.GOMAXPROCS(cpuNum - 1)
	fmt.Println("Ok")
}

输出：Ok
通过for循环一次开启多个协程
package main

import (
	"fmt"
	"sync"
)

var wg sync.WaitGroup

func Test(num int) {
	defer wg.Done()
	for i := 0; i < 5; i++ {
		fmt.Printf("协程(%v)，这是第%v次循环\n", num, i+1)
	}
}

func main() {
	for i := 1; i <= 5; i++ {
		wg.Add(1)
		go Test(i)
	}
	wg.Wait()
	fmt.Println("关闭协程")
}
